from fractions import Fraction

def step(poly, swap, d):
    out={}
    for p,a in poly.items():
        pp=list(p); i,j=swap; pp[i],pp[j]=pp[j],pp[i]; pp=tuple(pp)
        out[p]=out.get(p,Fraction())+a*d/(d-1)
        out[pp]=out.get(pp,Fraction())-a/(d-1)
    return {p:a for p,a in out.items() if a}
for K in range(1,7):
    ys=[3*i*i+2*i+1 for i in range(K)]
    factors=[((i,j),Fraction(ys[i]-ys[j])) for i in range(1,K) for j in range(i)]
    identity={tuple(range(K)):Fraction(1)}
    forward=identity; reverse=identity
    for pair,d in factors: forward=step(forward,pair,d)
    for pair,d in reversed(factors): reverse=step(reverse,pair,d)
    assert forward==reverse
    cancellation=forward
    for pair,d in factors: cancellation=step(cancellation,pair,-d)
    assert cancellation==identity
